var SEQ=1;
function add(list, text){ if(!text||!text.trim()) return list; return list.concat([{id:SEQ++, text:text.trim(), ts:Date.now()}]); }
function remove(list, id){ return list.filter(function(x){ return x.id!==id; }); }
function search(list, q){ q=(q||'').trim().toLowerCase(); if(!q) return list; return list.filter(function(x){ return x.text.toLowerCase().indexOf(q)>=0; }); }
var EXPORTS={add:add,remove:remove,search:search};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.ClipboardForgePure = EXPORTS; }
